import{j as t}from"./index-DOrUugLf.js";import{I as i}from"./InfoPage-wqhtNlpT.js";import"./PageHeader-BqqUK2Eb.js";const r=[["Aegrotat","A degree or examination result awarded in exceptional circumstances where a student could not sit an exam through illness."],["Bedder","The staff member, historically, responsible for making beds and cleaning rooms in colleges — now a familiar name for residential housekeeping staff."],["Boatie","A member of a college boat club."],["Common Room","A social room for students (Junior) or staff (Senior); also the elected body that runs student life at college level."],["Congregation","The governing body of the University, comprising academics and leading administrators, which approves regulations."],["Dean","The fellow in charge of discipline and welfare within a college."],["Fresher","A student in their first term at Brightwell."],["Fellow","A senior member of a college — often a tutor or researcher — elected to teach, guide and govern."],["Gaudy","A college reunion dinner for former students, typically held by year of matriculation."],["Hall","The dining hall of a college, or a residential institution without full collegiate status."],["Matriculation","The formal ceremony admitting you to the University; in many colleges you sign the matriculation register."],["Mods","Short for Moderations — the first university examinations, usually sat in the second or third term."],["Proctor","A senior officer responsible for discipline, elected each year to enforce university rules with the help of the proctors’ office."],["Scout","The college staff member who looks after your rooms, post and morning paper."],["Sizar","A historical status awarded to students of limited means; today the term survives in a small number of college scholarships."],["Tutorial","A weekly conversation between a tutor and one or two students — the teaching heart of a Brightwell education."],["Varsity","A fixture or competition between Brightwell and its great sporting rival."],["Vice-Chancellor","The chief academic and administrative officer of the University."]];function n(){return t.jsx(i,{title:"College glossary",lead:"New to Brightwell? Learn the language of the quadrangles — from matriculation to varsity — so you can talk like a member of the community from your first day.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"College glossary"}],sections:[{heading:"Words you will hear in your first week",intro:"The glossary below covers the terms used across the collegiate University. Not every college uses every word, but these are the ones most commonly heard on campus.",body:[],list:{items:r.map(([e,o])=>`${e} — ${o}`)}},{heading:"Looking for something else?",intro:"Your college’s handbook is the definitive guide to local language. If a phrase is missing here, ask your dean or your senior tutor — they have heard it all before.",body:["Colleges and halls also produce their own glossaries, reflecting traditions that go back over a century. The University registrar’s office keeps a full alphabetical guide to official regulations and offices."],aside:{title:"Visiting the University",body:"Guides lead free walking tours through the main campus and colleges throughout the year.",links:[["/visitors","Plan your visit"],["/about","About the University"]]}}]})}export{n as default};
